mapper.select:
SELECT STRFTIME('%Y-%m-%d %H:%M:%S', P.REG_DATE) AS regDate, P.SUB_NO AS subNo, P.USER_NO AS userNo, U.ID AS userId, U.NICKNAME AS userNickname, P.IS_ACTIVE AS active, P.DEVICE_ID AS deviceId, P.BROWSER AS browser, P.OS AS os, P.FAIL_COUNT AS failCount, STRFTIME('%Y-%m-%d %H:%M:%S', P.LAST_PUSH_DATE) AS lastPushDate FROM MB_PUSH_SUB P LEFT JOIN MB_USER U ON U.USER_NO = P.USER_NO WHERE STRFTIME('%Y-%m-%d', P.REG_DATE) = #{date}
AND ( UPPER(U.ID) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(U.NICKNAME) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(COALESCE(P.DEVICE_ID, '')) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(COALESCE(P.BROWSER, '')) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(COALESCE(P.OS, '')) LIKE '%' || UPPER(#{keyword}) || '%' )
ORDER BY P.SUB_NO DESC LIMIT 20 OFFSET #{offset}
